window.promoIndex=window.promoIndex||0;
window.promoSeconds=10;
function renderPromo(){
 const root=$('#promo-dock'); if(!root)return;
 const section=(location.hash.slice(1)||'home').split('/')[0];
 if(!['home','tours','flights','hotels','destinations','guide'].includes(section)){root.hidden=true;return}
 try{if(sessionStorage.getItem('aeronova-promo-hidden')==='1'){root.hidden=true;return}}catch{}
 const offer=promoCampaigns[window.promoIndex%promoCampaigns.length],tour=tours.find(x=>x.id===offer.id);
 if(!tour)return;
 const was=Math.round(tour.price/(1-offer.discount/100)/10)*10;
 root.hidden=false;
 root.innerHTML=`<div class="promo-card"><button class="promo-close" type="button" data-premium-action="close-promo" aria-label="Taklifni yopish">×</button><div class="promo-image"><img src="${imgs[tour.image]}" alt="${tour.city} manzarasi"><span>${offer.tag}</span></div><div class="promo-copy"><p class="promo-country">${tour.country} · ${tour.days} KUN</p><h2>${offer.headline}</h2><p class="promo-detail">${offer.detail}</p><div class="promo-price"><del>${money(was)}</del><strong>${money(tour.price)} <small>/ kishi</small></strong><span>−${offer.discount}%</span></div><a class="promo-more" href="#tour/${tour.id}">Batafsil <b>↗</b></a></div><div class="promo-timer" aria-label="Keyingi taklif ${window.promoSeconds} soniyada"><span style="--promo-progress:${window.promoSeconds*10}%"></span><b data-countdown>${String(window.promoSeconds).padStart(2,'0')}</b><small>soniya</small></div><p class="promo-disclaimer">Demo aksiya · narxlar namunaviy</p></div>`;
}
function closeWelcome(){const intro=$('#premium-welcome');if(!intro||intro.hidden)return;intro.classList.add('welcome-exit');window.setTimeout(()=>{intro.hidden=true;intro.classList.remove('welcome-exit')},420);}
function startWelcome(){
 const intro=$('#premium-welcome');if(!intro)return;
 let seen=false;try{seen=sessionStorage.getItem('aeronova-welcome-seen')==='1';if(!seen)sessionStorage.setItem('aeronova-welcome-seen','1')}catch{}
 if(seen){intro.hidden=true;return}
 intro.hidden=false;
 $('#welcome-start')?.focus({preventScroll:true});
 $('#welcome-start')?.addEventListener('click',closeWelcome,{once:true});
 window.setTimeout(closeWelcome,2200);
}
$('#promo-dock')?.addEventListener('click',e=>{if(!e.target.closest('[data-premium-action="close-promo"]'))return;try{sessionStorage.setItem('aeronova-promo-hidden','1')}catch{};$('#promo-dock').hidden=true});
$('#scroll-top')?.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));
let premiumLastScroll=window.scrollY;
window.addEventListener('scroll',()=>{const y=window.scrollY,up=y<premiumLastScroll-4;const btn=$('#scroll-top');if(btn){btn.classList.toggle('visible',y>360&&up);btn.setAttribute('aria-hidden',String(!(y>360&&up)))}premiumLastScroll=y},{passive:true});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeWelcome()});
renderPromo();startWelcome();
window.addEventListener('hashchange',()=>window.setTimeout(renderPromo,0));
window.setInterval(()=>{const dock=$('#promo-dock');if(!dock||dock.hidden||document.hidden||dock.matches(':hover')||dock.contains(document.activeElement))return;if(window.promoSeconds>1){window.promoSeconds--;const n=$('#promo-dock [data-countdown]'),ring=$('#promo-dock .promo-timer>span'),timer=$('#promo-dock .promo-timer');if(n)n.textContent=String(window.promoSeconds).padStart(2,'0');if(ring)ring.style.setProperty('--promo-progress',`${window.promoSeconds*10}%`);if(timer)timer.setAttribute('aria-label',`Keyingi taklif ${window.promoSeconds} soniyada`)}else{window.promoIndex=(window.promoIndex+1)%promoCampaigns.length;window.promoSeconds=10;renderPromo()}},1000);

// Keep every section modal consistent and let it close with the same soft motion.
const renderModalInstantly=modal;
const closeModalInstantly=closeModal;
modal=function(title,body){
 const m=$('#modal');
 clearTimeout(window.aeroModalCloseTimer);
 m.classList.remove('modal-closing');
 renderModalInstantly(title,body);
};
closeModal=function(){
 const m=$('#modal');
 if(!m?.open)return;
 clearTimeout(window.aeroModalCloseTimer);
 m.classList.add('modal-closing');
 window.aeroModalCloseTimer=setTimeout(()=>{
  if(m.open&&m.classList.contains('modal-closing')){
   m.classList.remove('modal-closing');
   closeModalInstantly();
  }
 },240);
};
$('#modal')?.addEventListener('cancel',e=>{e.preventDefault();closeModal()});
$('#modal')?.addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
const premiumModal=$('#modal');
let modalDragStart=null;
premiumModal?.addEventListener('pointerdown',e=>{
 if(!e.target.closest('.modalhead')||e.target.closest('button')||matchMedia('(min-width:681px)').matches)return;
 modalDragStart={y:e.clientY,id:e.pointerId};
 premiumModal.setPointerCapture?.(e.pointerId);
});
premiumModal?.addEventListener('pointermove',e=>{
 if(!modalDragStart||modalDragStart.id!==e.pointerId)return;
 const dy=Math.max(0,e.clientY-modalDragStart.y);
 premiumModal.classList.add('modal-dragging');
 premiumModal.style.setProperty('--modal-drag-y',`${dy}px`);
});
const finishModalDrag=e=>{
 if(!modalDragStart||modalDragStart.id!==e.pointerId)return;
 const dy=Math.max(0,e.clientY-modalDragStart.y);
 modalDragStart=null;
 premiumModal.classList.remove('modal-dragging');
 premiumModal.style.removeProperty('--modal-drag-y');
 if(dy>110)closeModal();
};
premiumModal?.addEventListener('pointerup',finishModalDrag);
premiumModal?.addEventListener('pointercancel',finishModalDrag);

// Animate only true route changes; filter and form updates stay immediate.
const renderWithoutRouteMotion=render;
let activeRouteTransition=null;
render=function(){
 const next=location.hash.slice(1)||'home',changed=next!==currentRoute;
 if(!changed||matchMedia('(prefers-reduced-motion: reduce)').matches)return renderWithoutRouteMotion();
 if(typeof document.startViewTransition==='function'){
  try{
   activeRouteTransition?.skipTransition();
   const transition=document.startViewTransition(()=>renderWithoutRouteMotion());
   activeRouteTransition=transition;
   transition.finished.catch(()=>{}).finally(()=>{if(activeRouteTransition===transition)activeRouteTransition=null});
  }catch{
   renderWithoutRouteMotion();
  }
 }else{
  const app=$('#app');app?.classList.add('route-fallback');renderWithoutRouteMotion();
  requestAnimationFrame(()=>app?.classList.add('route-fallback-ready'));
  window.setTimeout(()=>app?.classList.remove('route-fallback','route-fallback-ready'),420);
 }
};

const baseGuideView=guide;
const popularSpots={istanbul:['Ayasofya','Galata minorasi','Bosfor','Sultonahmad'],dubai:['Burj Xalifa','Dubai Marina','Eski shahar','Palm Jumeirah'],thai:['Railay sohili','Phi Phi orollari','Ao Nang','Emerald Pool']};
function memoryGallery(city){
 const spots=popularSpots[city]||popularSpots.istanbul,photos=(state.memoryPhotos&&state.memoryPhotos[city])||[],totalPhotos=Object.values(state.memoryPhotos||{}).reduce((sum,list)=>sum+list.length,0),limitReached=totalPhotos>=5;
 return `<section class="memory-section"><div class="sectionhead"><div><span class="eyebrow blue-eyebrow">SAYOHAT XOTIRALARI</span><h2>Mashhur joylardan esdaliklar</h2><p>O‘zingiz olgan suratlarni joy bilan bog‘lab saqlang.</p></div><span class="memory-count">${totalPhotos} / 5 rasm</span></div><div class="memory-upload-row"><label class="field memory-place">Surat olingan joy<select id="memory-place">${spots.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label class="memory-upload ${limitReached?'disabled':''}"><input type="file" id="memory-upload" data-memory-city="${city}" accept="image/*" multiple ${limitReached?'disabled':''}><span class="memory-plus">＋</span><span><strong>${limitReached?'Limit to‘ldi':'Rasm tanlash'}</strong><small>Rasm fayllari · jami 5 tagacha</small></span></label></div>${photos.length?`<div class="memory-grid">${photos.map(p=>`<article class="memory-photo"><img src="${p.src}" alt="${esc(p.spot)} xotirasi"><span>${esc(p.spot)}</span><button type="button" aria-label="${esc(p.spot)} suratini o‘chirish" data-memory-remove="${esc(p.key)}" data-memory-city="${city}">×</button></article>`).join('')}</div>`:`<div class="memory-empty">${icon('globe')}<span>Hali surat yo‘q. Birinchi esdalik rasmingizni qo‘shing.</span></div>`}<p class="memory-note">Beta demo: suratlar siqilib, faqat shu brauzerda saqlanadi. Ular ommaviy galereyaga yuborilmaydi.</p></section>`;
}
guide=function(id){return baseGuideView(id)+memoryGallery(id)};
const baseProfileView=profile;
profile=function(){return `${baseProfileView()}<section class="panel account-entry"><span class="eyebrow blue-eyebrow">AERONOVA HISOBI</span><h2>${state.email?'Profilingiz tayyor':'Sayohatlaringizni bir joyda saqlang'}</h2><p class="muted">${state.email?esc(state.email):'Ro‘yxatdan o‘tib, safar rejalaringiz va yoqtirgan yo‘nalishlaringizni shu qurilmada tartibli saqlang.'}</p><div class="row"><button class="btn white" data-act="login">Kirish</button><button class="btn" data-act="auth-mode" data-id="register">Demo profil yaratish</button></div></section>`};
if(currentRoute.startsWith('guide/'))render();
async function compactMemoryPhoto(file){
 if(!file.type.startsWith('image/'))throw new Error('Faqat rasm fayllari qabul qilinadi.');
 if(file.size>20*1024*1024)throw new Error('Har bir rasm 20 MB dan kichik bo‘lishi kerak.');
 const bitmap=await createImageBitmap(file),scale=Math.min(1,960/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');
 canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));
 canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();
 return canvas.toDataURL('image/jpeg',.65);
}
document.addEventListener('change',async e=>{
 const input=e.target.closest('#memory-upload');if(!input||!input.files?.length)return;
 const city=input.dataset.memoryCity,existing=(state.memoryPhotos&&state.memoryPhotos[city])||[],files=Array.from(input.files),existingTotal=Object.values(state.memoryPhotos||{}).reduce((sum,list)=>sum+list.length,0);
 if(existingTotal+files.length>5){toast(`Jami yana faqat ${5-existingTotal} ta rasm qo‘sha olasiz.`);input.value='';return}
 const spot=$('#memory-place')?.value||'Sayohat xotirasi',y=window.scrollY;
 try{const added=[];for(const file of files)added.push({key:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`,spot,src:await compactMemoryPhoto(file)});state.memoryPhotos=state.memoryPhotos||{};state.memoryPhotos[city]=[...existing,...added];if(!persist()){state.memoryPhotos[city]=existing;toast('Brauzer xotirasi to‘ldi. Boshqa saqlangan rasmlarni o‘chirib, qayta urinib ko‘ring.');input.value='';return}render();window.scrollTo(0,y);toast(`${added.length} ta rasm xotiralarga saqlandi.`)}catch(err){toast(err.message||'Rasmni ochib bo‘lmadi. Boshqa rasm tanlang.');input.value=''}
});
document.addEventListener('click',e=>{
 const remove=e.target.closest('[data-memory-remove]');if(remove){const y=window.scrollY,city=remove.dataset.memoryCity;state.memoryPhotos[city]=(state.memoryPhotos[city]||[]).filter(p=>p.key!==remove.dataset.memoryRemove);persist();render();window.scrollTo(0,y);return}
 const action=e.target.closest('[data-act]')?.dataset.act;
 if(action==='login')showAuth('login');else if(action==='auth-mode')showAuth(e.target.closest('[data-act="auth-mode"]').dataset.id);
});
function showAuth(mode){
 const registering=mode==='register';
 if(registering){
  modal('Ro‘yxatdan o‘tish',`<p class="muted">Ismingiz va emailingiz bilan demo profil yarating.</p><form id="register-form" class="stack"><label class="field">Ism va familiya<input name="name" autocomplete="name" minlength="2" maxlength="50" required placeholder="Ismingiz"></label><label class="field">Email manzil<input name="email" type="email" autocomplete="email" required placeholder="siz@example.com"></label><p class="auth-note">Bu demo profil: parol so‘ralmaydi va haqiqiy hisob yaratmaydi. Ma’lumotlar faqat shu brauzerda saqlanadi.</p><button class="btn full">Demo profil yaratish</button></form><button class="textbtn full" data-act="auth-mode" data-id="login">Hisobingiz bormi? Kirish</button>`);
 }else{
  const name=state.user==='Mehmon'?'':esc(state.user);
  modal('AeroNova’ga xush kelibsiz',`<p class="muted">Demo hisob bilan bo‘limlarni sinang. Haqiqiy kirish va SMS tasdiqlash ulanmagan.</p><form id="login-form"><label class="field">Ismingiz<input name="name" autocomplete="name" placeholder="Ismingiz" value="${name}" minlength="2" maxlength="50" required></label><button class="btn full">Demo hisobga kirish</button></form><button class="textbtn full" data-act="auth-mode" data-id="register" style="margin-top:10px">Yangi mijozmisiz? Ro‘yxatdan o‘tish</button>`);
 }
}
document.addEventListener('submit',e=>{
 const form=e.target;if(form.id!=='register-form')return;e.preventDefault();const data=new FormData(form),name=String(data.get('name')||'').trim(),email=String(data.get('email')||'').trim();
 if(!name||!email){toast('Ism va emailni tekshiring.');return}
 state.user=name;state.email=email;persist();closeModal();render();toast(`Xush kelibsiz, ${name}! Demo profilingiz tayyor.`);
});
